changeSet.sql:
ALTER TABLE zc_medication_coordination
  ADD CONSTRAINT fk_zc_medication_coordination_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_medication_coordination
  ADD CONSTRAINT fk_zc_medication_coordination_enrolment FOREIGN KEY (tenant_id, enrolment_id)
    REFERENCES zc_enrolment (tenant_id, id);

ALTER TABLE zc_refill_request
  ADD CONSTRAINT fk_zc_refill_request_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_refill_request
  ADD CONSTRAINT fk_zc_refill_request_enrolment FOREIGN KEY (tenant_id, enrolment_id)
    REFERENCES zc_enrolment (tenant_id, id);
ALTER TABLE zc_refill_request
  ADD CONSTRAINT fk_zc_refill_request_medication_coordination
    FOREIGN KEY (tenant_id, medication_coordination_id, enrolment_id)
    REFERENCES zc_medication_coordination (tenant_id, id, enrolment_id);

ALTER TABLE zc_adherence_event
  ADD CONSTRAINT fk_zc_adherence_event_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_adherence_event
  ADD CONSTRAINT fk_zc_adherence_event_enrolment FOREIGN KEY (tenant_id, enrolment_id)
    REFERENCES zc_enrolment (tenant_id, id);
ALTER TABLE zc_adherence_event
  ADD CONSTRAINT fk_zc_adherence_event_medication_coordination
    FOREIGN KEY (tenant_id, medication_coordination_id, enrolment_id)
    REFERENCES zc_medication_coordination (tenant_id, id, enrolment_id);

-- Tenant isolation. The app must connect as zc_app: superusers bypass RLS.
ALTER TABLE zc_medication_coordination ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_medication_coordination FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_medication_coordination_tenant ON zc_medication_coordination
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_refill_request ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_refill_request FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_refill_request_tenant ON zc_refill_request
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_adherence_event ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_adherence_event FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_adherence_event_tenant ON zc_adherence_event
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());

rollback.sql:
DROP POLICY rls_zc_medication_coordination_tenant ON zc_medication_coordination;
ALTER TABLE zc_medication_coordination NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_medication_coordination DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_refill_request_tenant ON zc_refill_request;
ALTER TABLE zc_refill_request NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_refill_request DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_adherence_event_tenant ON zc_adherence_event;
ALTER TABLE zc_adherence_event NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_adherence_event DISABLE ROW LEVEL SECURITY;

changeSet.sql:
GRANT SELECT, INSERT, UPDATE ON zc_medication_coordination TO zc_app;
GRANT USAGE ON SEQUENCE zc_medication_coordination_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_refill_request TO zc_app;
GRANT USAGE ON SEQUENCE zc_refill_request_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_adherence_event TO zc_app;
GRANT USAGE ON SEQUENCE zc_adherence_event_id_seq TO zc_app;

rollback.sql:
REVOKE ALL ON zc_medication_coordination FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_medication_coordination_id_seq FROM zc_app;
REVOKE ALL ON zc_refill_request FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_refill_request_id_seq FROM zc_app;
REVOKE ALL ON zc_adherence_event FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_adherence_event_id_seq FROM zc_app;
